# -*- coding: utf-8 -*-
import zlib, base64, sys, py_compile
try: sys.stdout.reconfigure(encoding="utf-8")
except: pass
DATA = ""
code = zlib.decompress(base64.b64decode(DATA)).decode("utf-8")
open("agent.py", "w", encoding="utf-8").write(code)
py_compile.compile("agent.py", doraise=True)
print("agent.py بازسازی شد — بدون خطا!")